-- Reconciliação de proveniência dos 389 acessórios preexistentes no Atlas
-- confirmados na fonte W.Vetro em 2026-08-16/17.
--
-- Objetivo:
--   enriquecer somente a proveniência externa dos registros já existentes,
--   sem alterar a unidade operacional Atlas nem outros dados comerciais/técnicos.
--
-- Escopo auditado:
--   296 EXISTENTE_IGUAL;
--    93 EXISTENTE_DIVERGENTE apenas em unidade:
--       MT->UN 66, PR->UN 12, TB->UN 9, BR->UN 3, PT->UN 2, PC->UN 1.
--
-- NÃO altera: unidade, nome, descrição, categoria, preço/custo, NCM operacional,
-- marca operacional, ativo, linha_id, cor_id ou id_externo_wvetro.
--
-- A migration aborta se os IDs/códigos/unidades Atlas não coincidirem com o
-- snapshot reconciliado, evitando aplicar proveniência sobre registros alterados.

begin;

create temporary table _reconciliacao_acessorios_wvetro_existentes (
  codigo_origem_raw text not null,
  descricao_fonte text not null,
  unidade_fonte text not null,
  ncm_fonte text,
  linha_origem text,
  cor_origem text,
  fabricante_origem text,
  status_fonte text,
  motivos_fonte text,
  status_reconciliacao text not null,
  motivos_divergencia text,
  flags_revisao text,
  atlas_id uuid not null,
  atlas_unidade_esperada text not null,
  qtde_embalagem numeric,
  ativo_fonte text
) on commit drop;

insert into _reconciliacao_acessorios_wvetro_existentes (
  codigo_origem_raw,
  descricao_fonte,
  unidade_fonte,
  ncm_fonte,
