-- Guardas de escopo + snapshot Atlas.
do $$
declare
  v_total integer;
  v_ids_duplicados integer;
  v_codigos_duplicados integer;
  v_status_invalido integer;
  v_distribuicao_status_invalida integer;
  v_distribuicao_divergencia_invalida integer;
  v_inativos integer;
  v_ids_ausentes integer;
  v_codigo_drift integer;
  v_unidade_drift integer;
  v_categoria_invalida integer;
begin
  select count(*) into v_total
  from _reconciliacao_acessorios_wvetro_existentes;
  if v_total <> 389 then
    raise exception 'Reconciliação esperava 389 linhas; encontrou %', v_total;
  end if;

  select count(*) into v_ids_duplicados
  from (
    select atlas_id
    from _reconciliacao_acessorios_wvetro_existentes
    group by atlas_id
    having count(*) > 1
  ) x;
  if v_ids_duplicados <> 0 then
    raise exception 'Reconciliação contém % Atlas ID(s) duplicado(s)', v_ids_duplicados;
  end if;

  select count(*) into v_codigos_duplicados
  from (
    select upper(regexp_replace(trim(codigo_origem_raw), '\s+', ' ', 'g')) as codigo_norm
    from _reconciliacao_acessorios_wvetro_existentes
    group by 1
    having count(*) > 1
  ) x;
  if v_codigos_duplicados <> 0 then
    raise exception 'Reconciliação contém % código(s) fonte normalizado(s) duplicado(s)', v_codigos_duplicados;
  end if;

  select count(*) into v_status_invalido
  from _reconciliacao_acessorios_wvetro_existentes
  where status_reconciliacao not in ('EXISTENTE_IGUAL', 'EXISTENTE_DIVERGENTE');
  if v_status_invalido <> 0 then
    raise exception 'Reconciliação contém % status fora do escopo existente', v_status_invalido;
  end if;

  select count(*) into v_distribuicao_status_invalida
  from (
    with esperado(status_reconciliacao, quantidade) as (
      values ('EXISTENTE_IGUAL', 296), ('EXISTENTE_DIVERGENTE', 93)
    ),
    atual as (
      select status_reconciliacao, count(*)::integer as quantidade
      from _reconciliacao_acessorios_wvetro_existentes
      group by 1
    )
    select coalesce(e.status_reconciliacao, a.status_reconciliacao)
    from esperado e
    full join atual a using (status_reconciliacao)
    where coalesce(e.quantidade, -1) <> coalesce(a.quantidade, -1)
  ) x;
  if v_distribuicao_status_invalida <> 0 then
    raise exception 'Distribuição igual/divergente não coincide com a auditoria 296/93';
  end if;

  select count(*) into v_distribuicao_divergencia_invalida
  from (
    with esperado(unidade_fonte, unidade_atlas, quantidade) as (
      values
        ('MT','UN',66),
        ('PR','UN',12),
        ('TB','UN',9),
        ('BR','UN',3),
        ('PT','UN',2),
        ('PC','UN',1)
    ),
    atual as (
      select upper(trim(unidade_fonte)) as unidade_fonte,
             upper(trim(atlas_unidade_esperada)) as unidade_atlas,
             count(*)::integer as quantidade
      from _reconciliacao_acessorios_wvetro_existentes
      where status_reconciliacao = 'EXISTENTE_DIVERGENTE'
      group by 1,2
    )
    select coalesce(e.unidade_fonte, a.unidade_fonte),
           coalesce(e.unidade_atlas, a.unidade_atlas)
    from esperado e
    full join atual a using (unidade_fonte, unidade_atlas)
    where coalesce(e.quantidade, -1) <> coalesce(a.quantidade, -1)
  ) x;
  if v_distribuicao_divergencia_invalida <> 0 then
    raise exception 'Distribuição das 93 divergências de unidade não coincide com a auditoria';
  end if;

  select count(*) into v_inativos
  from _reconciliacao_acessorios_wvetro_existentes
  where lower(trim(coalesce(ativo_fonte, ''))) not in ('sim','true','1','t');
  if v_inativos <> 0 then
    raise exception 'Reconciliação contém % item(ns) não ativos na fonte', v_inativos;
  end if;

  select count(*) into v_ids_ausentes
  from _reconciliacao_acessorios_wvetro_existentes c
  left join public.produtos p on p.id = c.atlas_id
  where p.id is null;
  if v_ids_ausentes <> 0 then
    raise exception 'Snapshot Atlas mudou: % ID(s) reconciliado(s) não existem mais', v_ids_ausentes;
  end if;

  select count(*) into v_categoria_invalida
  from _reconciliacao_acessorios_wvetro_existentes c
  join public.produtos p on p.id = c.atlas_id
  where p.categoria <> 'acessorio';
  if v_categoria_invalida <> 0 then
    raise exception 'Snapshot Atlas mudou: % ID(s) deixaram de ser acessório', v_categoria_invalida;
  end if;

  select count(*) into v_codigo_drift
  from _reconciliacao_acessorios_wvetro_existentes c
  join public.produtos p on p.id = c.atlas_id
  where upper(trim(coalesce(p.codigo, ''))) <>
        upper(regexp_replace(trim(c.codigo_origem_raw), '\s+', ' ', 'g'));
  if v_codigo_drift <> 0 then
    raise exception 'Snapshot Atlas mudou: % código(s) não coincidem mais com a reconciliação', v_codigo_drift;
  end if;

  select count(*) into v_unidade_drift
  from _reconciliacao_acessorios_wvetro_existentes c
  join public.produtos p on p.id = c.atlas_id
  where p.unidade is distinct from c.atlas_unidade_esperada;
  if v_unidade_drift <> 0 then
    raise exception 'Snapshot Atlas mudou: % unidade(s) operacionais diferem da reconciliação; nenhuma será sobrescrita', v_unidade_drift;
  end if;
end $$;

-- Snapshot temporário dos campos que esta migration promete não modificar.
create temporary table _atlas_operacional_antes on commit drop as
select
  p.id,
  p.nome,
  p.categoria,
  p.preco,
  p.unidade,
  p.descricao,
  p.ativo,
  p.marca,
  p.ncm,
  p.linha_id,
  p.cor_id,
  p.id_externo_wvetro
from public.produtos p
join _reconciliacao_acessorios_wvetro_existentes c on c.atlas_id = p.id;

-- Enriquecimento exclusivamente de proveniência.
update public.produtos p
set
  codigo_origem = c.codigo_origem_raw,
  origem = 'wvetro',
  unidade_origem = upper(trim(c.unidade_fonte)),
  qtde_embalagem_origem = c.qtde_embalagem,
  dados_origem = coalesce(p.dados_origem, '{}'::jsonb) || jsonb_build_object(
    'fonte', 'ExportWWAcessorios.xlsx',
    'reconciliacao', '2026-08-16/17',
    'codigo_raw', c.codigo_origem_raw,
    'descricao_raw', c.descricao_fonte,
    'unidade_raw', c.unidade_fonte,
    'ncm_raw', c.ncm_fonte,
    'linha_raw', c.linha_origem,
    'cor_raw', c.cor_origem,
    'fabricante_raw', c.fabricante_origem,
    'qtde_emb_raw', c.qtde_embalagem,
    'ativo_raw', c.ativo_fonte,
    'status_fonte', c.status_fonte,
    'motivos_fonte', c.motivos_fonte,
    'flags_revisao', c.flags_revisao,
    'status_reconciliacao', c.status_reconciliacao,
    'motivos_divergencia', c.motivos_divergencia
  ),
  ncm_origem = nullif(trim(c.ncm_fonte), ''),
  observacao_validacao = case
    when coalesce(p.observacao_validacao, '') like '%Proveniência W.Vetro reconciliada em 2026-08-17%'
      then p.observacao_validacao
    else concat_ws(
      E'\n',
      nullif(trim(p.observacao_validacao), ''),
      'Proveniência W.Vetro reconciliada em 2026-08-17. Unidade operacional Atlas preservada; unidade da fonte armazenada separadamente em unidade_origem. Nenhuma conversão foi inferida.'
    )
  end,
  updated_at = now()
from _reconciliacao_acessorios_wvetro_existentes c
where p.id = c.atlas_id;

-- Pós-checks: proveniência completa e zero alteração nos campos protegidos.
do $$
declare
  v_atualizados integer;
  v_proveniencia_incompleta integer;
  v_operacional_alterado integer;
  v_divergentes_preservados integer;
  v_iguais_preservados integer;
begin
  select count(*) into v_atualizados
  from public.produtos p
  join _reconciliacao_acessorios_wvetro_existentes c on c.atlas_id = p.id
  where p.origem = 'wvetro';
  if v_atualizados <> 389 then
    raise exception 'Pós-reconciliação esperava 389 produtos com origem wvetro; encontrou %', v_atualizados;
  end if;

  select count(*) into v_proveniencia_incompleta
  from public.produtos p
  join _reconciliacao_acessorios_wvetro_existentes c on c.atlas_id = p.id
  where p.codigo_origem is distinct from c.codigo_origem_raw
     or p.unidade_origem is distinct from upper(trim(c.unidade_fonte))
     or p.qtde_embalagem_origem is distinct from c.qtde_embalagem
     or p.ncm_origem is distinct from nullif(trim(c.ncm_fonte), '')
     or p.dados_origem ->> 'fonte' is distinct from 'ExportWWAcessorios.xlsx'
     or p.dados_origem ->> 'status_reconciliacao' is distinct from c.status_reconciliacao;
  if v_proveniencia_incompleta <> 0 then
    raise exception 'Pós-reconciliação encontrou % registro(s) com proveniência incompleta', v_proveniencia_incompleta;
  end if;

  select count(*) into v_operacional_alterado
  from _atlas_operacional_antes a
  join public.produtos p on p.id = a.id
  where p.nome is distinct from a.nome
     or p.categoria is distinct from a.categoria
     or p.preco is distinct from a.preco
     or p.unidade is distinct from a.unidade
     or p.descricao is distinct from a.descricao
     or p.ativo is distinct from a.ativo
     or p.marca is distinct from a.marca
     or p.ncm is distinct from a.ncm
     or p.linha_id is distinct from a.linha_id
     or p.cor_id is distinct from a.cor_id
     or p.id_externo_wvetro is distinct from a.id_externo_wvetro;
  if v_operacional_alterado <> 0 then
    raise exception 'Pós-reconciliação detectou % registro(s) com campo operacional alterado indevidamente', v_operacional_alterado;
  end if;

  select count(*) into v_divergentes_preservados
  from public.produtos p
  join _reconciliacao_acessorios_wvetro_existentes c on c.atlas_id = p.id
  where c.status_reconciliacao = 'EXISTENTE_DIVERGENTE'
    and p.unidade = c.atlas_unidade_esperada
    and p.unidade_origem = upper(trim(c.unidade_fonte));
  if v_divergentes_preservados <> 93 then
    raise exception 'Esperava preservar 93 divergências de unidade; confirmou %', v_divergentes_preservados;
  end if;

  select count(*) into v_iguais_preservados
  from public.produtos p
  join _reconciliacao_acessorios_wvetro_existentes c on c.atlas_id = p.id
  where c.status_reconciliacao = 'EXISTENTE_IGUAL'
    and p.unidade = c.atlas_unidade_esperada
    and p.unidade_origem = upper(trim(c.unidade_fonte));
  if v_iguais_preservados <> 296 then
    raise exception 'Esperava confirmar 296 unidades iguais; confirmou %', v_iguais_preservados;
  end if;
end $$;

commit;
